window.AUTH=window.AUTH||{};window.AUTH["19-1414"]={"d":"19-1414","id":"2020/19-1414","n":"United States v. Cooley","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2021-01-08","url":"https://www.supremecourt.gov/DocketPDF/19/19-1414/165737/20210108153036386_19-1414tsUnitedStates.pdf","side":"pet","n":63},{"k":"respondent","label":"Brief of respondent Joshua James Cooley","date":"2021-02-12","url":"https://www.supremecourt.gov/DocketPDF/19/19-1414/168888/20210212123501425_Cooley%20Respondent%20Brief_FINAL.pdf","side":"res","n":41},{"k":"reply","label":"Reply of petitioner United States","date":"2021-03-12","url":"https://www.supremecourt.gov/DocketPDF/19/19-1414/171761/20210312122720663_19-1414%20Cooley%20Reply.pdf","side":"pet","n":45}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r40_j5fl.pdf","tr":true,"items":[{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"by":{"0":"18","1":"17, 18","2":"3"},"q":[{"src":"brief","b":0,"text":"that state and local officers generally have authority to make stops and arrests for violations of federal criminal laws.","cite":"567 U.S. 387, 447"},{"src":"brief","b":2,"text":"States, as sovereigns, have inherent authority to conduct arrests for violations of federal law, unless and until Congress removes that authority.","cite":"567 U.S. 387, 438"}]},{"t":"case","label":"Atkinson Trading Co. v. Shirley","cite":"532 U.S. 645","y":2001,"id":"2000/00-454","sc":1,"by":{"0":"24","1":"14, 24","2":"11, 13"},"q":[{"src":"brief","b":1,"text":"[o]nly full territorial sovereigns enjoy the ‘power to enforce laws against all who come within the sovereign’s territory, whether citizens or aliens,’ and Indian tribes ‘can no longer be described as sovereigns in this sense.’","cite":"532 U.S. 645, 654"},{"src":"brief","b":1,"text":"[s]ection 1151 simply does not address an Indian tribe’s inherent authority over nonmembers on non-Indian fee land.","cite":"532 U.S. at 653 n.5"},{"src":"argument","who":"Mr. Feigin","text":"Well, I think the Court essentially recognized that there's a distinction or at least nodded at such a distinction in both Strate and Atkinson when it expressly noted that it wasn't questioning this particular power that we're discussing here today, which is the power to stop and detain someone on public rights-of-way that run through a reservation, that the --"},{"src":"argument","who":"Mr. Feigin","text":"I think it's pretty clear from Strate and I -- I believe Your Honor's opinion in Atkinson that the authority we're talking about today is meaningfully different."},{"src":"argument","who":"Mr. Feigin","text":"Well, I do think it has broader implications for Indian sovereignty, and I -- I would urge the Court to keep Montana where -- where I think it has always been. And I do think Strate and Atkinson reflect an understanding by the Court that this isn't a Montana situation, but --"}]},{"t":"case","label":"Atwater v. City of Lago Vista","cite":"532 U.S. 318","y":2001,"id":"2000/99-1408","sc":1,"by":{"0":"35","2":"17"},"q":[{"src":"brief","b":0,"text":"ha[ve] to be applied on the spur (and in the heat) of the moment.","cite":"532 U.S. 318, 347"},{"src":"brief","b":2,"text":"on the spur (and in the heat) of the moment.","cite":"532 U.S. 318, 347-348"}]},{"t":"case","label":"Beck v. Ohio","cite":"379 U.S. 89","y":1964,"id":"1964/18","sc":1,"by":{"0":"34"}},{"t":"case","label":"Big Horn County Elec. Coop., Inc. v. Adams","cite":"219 F.3d 944","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/944/","by":{"0":"38"}},{"t":"case","label":"Brendale v. Confederated Tribes & Bands of the Yakima Indian Nation","cite":"492 U.S. 408","y":1989,"id":"1988/87-1622","sc":1,"by":{"0":"32","1":"19"},"q":[{"src":"brief","b":0,"text":"tribes have inherent sovereignty independent of th[e] authority arising from their power to exclude.","cite":"492 U.S. 408, 425"}]},{"t":"case","label":"Bressi v. Ford","cite":"575 F.3d 891","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/575/891/","by":{"0":"8, 33"},"q":[{"src":"brief","b":0,"text":"‘a state or federal law has been violated.’","cite":"575 F.3d 891, 896"}]},{"t":"case","label":"Clark v. Fort Peck Tribes","cite":"15 Am. Tribal Law 203","y":2018,"court":"Fort Peck Ct. App.","url":"https://www.courtlistener.com/c/Am.%20Tribal%20Law/15/203/","by":{"0":"34"}},{"t":"case","label":"Colyer v. State","cite":"203 P.3d 1104","y":2009,"court":"Wyo.","url":"https://www.courtlistener.com/c/P.3d/203/1104/","by":{"0":"36"}},{"t":"case","label":"Duro v. Reina","cite":"495 U.S. 676","y":1990,"id":"1989/88-6546","sc":1,"by":{"0":"3, 22, 23, 34","1":"passim","2":"11, 12, 13, 17"},"q":[{"src":"brief","b":0,"text":"exercise of criminal jurisdiction subjects a person not only to the adjudicatory power of the tribunal, but also to the prosecuting power of the tribe,","cite":"495 U.S. 676, 688"},{"src":"brief","b":0,"text":"[w]here jurisdiction to try and punish an offender rests outside the tribe, tribal officers may exercise their power to detain the offender and transport him to the proper authorities.","cite":"495 U.S. at 697"},{"src":"brief","b":1,"text":"The tribes also possess their traditional and undisputed power to exclude persons whom they deem to be un desirable from tribal lands.","cite":"495 U.S. at 696"},{"src":"brief","b":1,"text":"If the present jurisdictional scheme proves insufficient to meet the practical needs of reservation law enforcement, then the proper body to address the problem is Congress, which has the ultimate authority over Indian affairs.","cite":"495 U.S. at 698"},{"src":"brief","b":2,"text":"trial by political bodies that do not include them.","cite":"495 U.S. at 693"},{"src":"argument","who":"Justice Kavanaugh","text":"And with that in mind, there are statements in our decisions in Duro and Strate that really cut directly against you, as you're -- you're well aware."},{"src":"argument","who":"Mr. Henkel","text":"I -- I -- I think those statements are -- the problem with those beyond -- you're -- you're right, I -- I think they're dicta, and I think that they -- Duro, for example, was talking about the exclusion power, which we don't have here."},{"src":"argument","who":"Mr. Henkel","text":"And that is far -- I -- I don't think this Court was saying anything like that in Duro or in Strate. It was just they have a general power to eject outsiders from reservations."}]},{"t":"case","label":"Florida v. Harris","cite":"568 U.S. 237","y":2013,"id":"2012/11-817","sc":1,"by":{"0":"43"}},{"t":"case","label":"Heien v. North Carolina","cite":"574 U.S. 54","y":2014,"id":"2014/13-604","sc":1,"by":{"0":"34"}},{"t":"case","label":"Herrera v. Wyoming","cite":"139 S. Ct. 1686","y":2019,"id":"2018/17-532","sc":1,"by":{"0":"2","2":"8"},"q":[{"src":"brief","b":0,"text":"The Crow Tribe first inhabited modern-day Montana more than three centuries ago.","cite":"139 S. Ct. 1686, 1692"}]},{"t":"case","label":"Manigault v. Springs","cite":"199 U.S. 473","y":1905,"id":"scdb/1905-037","sc":1,"by":{"0":"18"}},{"t":"case","label":"Merrion v. Jicarilla Apache Tribe","cite":"455 U.S. 130","y":1982,"id":"1980/80-11","sc":1,"by":{"0":"26, 32"}},{"t":"case","label":"Miller v. United States","cite":"357 U.S. 301","y":1958,"id":"1957/126","sc":1,"by":{"0":"18","2":"3"},"q":[{"src":"brief","b":2,"text":"to be determined by reference to state law.","cite":"357 U.S. 301, 305"}]},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"by":{"0":"2, 25, 26, 38","1":"11, 15, 16, 17, 24","2":"5, 11"},"q":[{"src":"brief","b":0,"text":"to slightly fewer than 2.3 million acres.","cite":"450 U.S. at 548"},{"src":"brief","b":0,"text":"the health or welfare of the tribe.","cite":"450 U.S. at 566"},{"src":"brief","b":1,"text":"autho rity to prohibit all hunting and fishing by nonmembers of the Tribe on non-Indian property within reservation boundaries.","cite":"450 U.S. at 547"},{"src":"brief","b":1,"text":"[the dissent] shuts both eyes to the reality that after Montana, tribal sovereignty over nonmembers ‘cannot survive without express congressional delegation’ and is therefore not inherent.","cite":"450 U.S. at 564"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"conduct [that] threatens or has some direct effect on . . . the health or welfare of the Page Proof Pending Publication tribe.","cite":"450 U. S. 544, 566"},{"src":"argument","who":"Chief Justice Roberts","text":"I would have thought Montana said the exact opposite. You know, you do argue at the outset there's this inherent authority and nothing took it away."},{"src":"argument","who":"Chief Justice Roberts","text":"Well, Montana -- Montana came after Colville. And -- and I'm not saying that we haven't recognized some inherent authority, but this is a question of tribal sovereignty over non-members, and I assume that would -- would extend to criminal jurisdiction."},{"src":"argument","who":"Mr. Feigin","text":"Well, let me make a couple points directly about Montana, Your Honor. I think Montana is how Colville shakes out in the civil, regulatory, and adjudicatory contexts."}]},{"t":"case","label":"Navarette v. California","cite":"572 U.S. 393","y":2014,"id":"2013/12-9490","sc":1,"by":{"0":"42"},"q":[{"src":"argument","who":"Mr. Feigin","text":"And it would curtail policing activity that everyone depends on, the ability to respond to a 911 call, like in Navarette, the ability to stop and frisk someone who's casing a jewelry store on non-tribal fee land, like in Terry against Ohio itself."}]},{"t":"case","label":"Negonsott v. Samuels","cite":"507 U.S. 99","y":1993,"id":"1992/91-5397","sc":1,"by":{"0":"3"}},{"t":"case","label":"Oklahoma Tax Comm’n v. Citizen Band Potawatomi Tribe of Okla.","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"exercise[d] inherent sovereign authority over their members and territories.","cite":"498 U.S. 505, 509"}]},{"t":"case","label":"Oliphant v. Suquamish Indian Tribe","cite":"435 U.S. 191","y":1978,"id":"1977/76-5729","sc":1,"by":{"0":"passim","1":"11, 12, 15, 26, 38","2":"5, 11, 12, 13, 17"},"q":[{"src":"brief","b":0,"text":"power to dispose of the soil at their own will, to whomsoever they pleased,","cite":"435 U.S. 191, 209"},{"src":"brief","b":0,"text":"[r]ead in conjunction with 18 U.S.C. § 1152, which extends federal enclave law to non-Indian offenses on Indian reservations, th[e] provision implies that the Suquamish are to promptly deliver up any nonIndian offender.","cite":"435 U.S. at 208"},{"src":"brief","b":1,"text":"great solicitude that its citizens be protected . . . from unwarranted intrusions on their personal liberty.","cite":"435 U.S. 191, 210"},{"src":"brief","b":1,"text":"In the absence of such legislation, however, Indians like other citizens are embraced within our Nation’s ‘great solicitude that its citizens be protected . . . from unwarranted intrusions on their personal liberty.’","cite":"435 U.S. at 210"},{"src":"brief","b":2,"text":"incorporation into the United States divested tribes of sovereignty over non-Indians ‘except in a manner acceptable to Congress.’","cite":"435 U.S. at 210"},{"src":"argument","who":"Mr. Henkel","text":"Those -- that line of argument, this Court said, completely overlooks the very reasons that cases like Montana and Oliphant and this one even exist, which is that the sovereign authority of Indian tribes is limited in ways state and federal authority is not."}]},{"t":"case","label":"Ornelas v. United States","cite":"517 U.S. 690","y":1996,"id":"1995/95-5257","sc":1,"by":{"0":"35"},"q":[{"src":"brief","b":0,"text":"legal rules for probable cause and reasonable suspicion acquire content only through application,","cite":"517 U.S. 690, 697"}]},{"t":"case","label":"Plains Commerce Bank v. Long Family Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"by":{"0":"18, 22, 24, 25, 26, 37","1":"passim","2":"14"},"q":[{"src":"brief","b":0,"text":"qualified to exercise many of the powers and prerogatives of self-government,","cite":"554 U.S. 316, 327"},{"src":"brief","b":0,"text":"general rule restrict[ing] tribal authority over nonmember activities * * * is particularly strong,","cite":"554 U.S. at 328"},{"src":"brief","b":1,"text":"by virtue of their incorporation into the American republic, [tribes] lost ‘the right of governing … person[s] within their limits except themselves.’","cite":"554 U.S. 316, 328"},{"src":"brief","b":1,"text":"efforts by a tribe to regulate nonmembers, especially on non-Indian fee land, are ‘presumptively invalid.’","cite":"554 U.S. at 330"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"cannot be construed in a manner that would swallow the rule.","cite":"554 U. S., at 330"},{"src":"argument","who":"Mr. Feigin","text":"After Lara, you have Plains Commerce Bank, which very clearly applies Montana in the contexts to which I -- I think it's clearly applicable, namely, civil, regulatory, and adjudicatory legislation."},{"src":"argument","who":"Mr. Henkel","text":"Chief Justice, I think we need to start by looking at what this Court said about the second Montana exception in Atkinson Trading Company and Plains Commerce Bank."},{"src":"argument","who":"Mr. Henkel","text":"I -- I think the first place to start is a line of analysis that this Court gave in Plains Commerce Bank, where the Court expressly rejected, you know, drawing some sort of parallel between tribal authority and what state and federal authorities they can do."}]},{"t":"case","label":"Seymour v. Superintendent of Wash. State Penitentiary","cite":"368 U.S. 351","y":1962,"id":"1961/62","sc":1,"by":{"0":"38"}},{"t":"case","label":"Solem v. Bartlett","cite":"465 U.S. 463","y":1984,"id":"1983/82-1253","sc":1,"by":{"0":"3"}},{"t":"case","label":"State v. Kurtz","cite":"249 P.3d 1271","y":2011,"court":"Or.","url":"https://www.courtlistener.com/c/P.3d/249/1271/","by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"[t]ribal officers are often the first responders to investigate offenses that occur on the reservation,","cite":"249 P.3d 1271, 1279"}]},{"t":"case","label":"State v. Madsen","cite":"760 N.W.2d 370","y":2009,"court":"S.D.","url":"https://www.courtlistener.com/c/N.W.2d/760/370/","by":{"0":"34"}},{"t":"case","label":"State v. Pamperien","cite":"967 P.2d 503","y":1998,"court":"Or. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/967/503/","by":{"0":"36"}},{"t":"case","label":"State v. Railey","cite":"532 P.2d 204","y":1975,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/532/204/","by":{"0":"34"}},{"t":"case","label":"State v. Ryder","cite":"649 P.2d 756","y":1981,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/649/756/","by":{"0":"36, 41"},"q":[{"src":"brief","b":0,"text":"To hold that an Indian police officer may stop offenders but upon determining they are non-Indians must let them go, would be to subvert a substantial function of Indian police authorities and produce a ludicrous state of affairs which would permit non-Indians to act unlawfully, with impunity, on Indian lands.","cite":"649 P.2d at 759"}]},{"t":"case","label":"State v. Salazar","cite":"461 P.3d 946","y":2020,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/461/946/","by":{"0":"39"}},{"t":"case","label":"State v. Schmuck","cite":"850 P.2d 1332","y":1993,"url":"https://www.courtlistener.com/c/P.2d/850/1332/","by":{"0":"24, 36, 37, 43, 46","1":"23"},"q":[{"src":"brief","b":0,"text":"careen[ing] off down the road, and possibly kill[ing] or injur[ing] Indians or nonIndians would certainly be detrimental to the health or welfare of the Tribe,","cite":"850 P.2d at 1341"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"[a]llowing a known drunk driver to get back in his or her car, careen off down the road, and possibly kill or injure Indians or non-Indians would certainly be detrimental to the health or welfare of the Tribe.","cite":"850 P. 2d 1332, 1341"}]},{"t":"case","label":"Strate v. A-1 Contractors","cite":"520 U.S. 438","y":1997,"id":"1996/95-1872","sc":1,"by":{"0":"12, 14, 21, 22, 24, 37","1":"15, 21, 22, 24, 25","2":"11, 13"},"q":[{"src":"brief","b":0,"text":"question[ed] the authority of tribal police to patrol roads within a reservation, including rights-ofway made part of a state highway, and to detain and turn over to state officers nonmembers stopped on the highway for conduct violating state law,","cite":"520 U.S. 438, 456 n.11"},{"src":"brief","b":0,"text":"[w]e do not here question the authority of tribal police to patrol roads within a reservation, including rights-of-way made part of a state highway, and to detain and turn over to state officers nonmembers stopped on the highway for conduct violating state law.","cite":"520 U.S. at 456 n.11"},{"src":"brief","b":1,"text":"As to nonmembers, we hold a tribe’s adjudicative jurisdiction does not exceed its legislative jurisdiction.","cite":"520 U.S. 438, 454"},{"src":"brief","b":1,"text":"We do not here question the authority of tribal police to patrol roads within a reservation, including rights-of-way made part of a state highway, and to detain and turn over to state officers nonme mbers stopped on the highway for conduct violating state law.","cite":"520 U.S. at 455"},{"src":"argument","who":"Mr. Feigin","text":"Well, I think the Court essentially recognized that there's a distinction or at least nodded at such a distinction in both Strate and Atkinson when it expressly noted that it wasn't questioning this particular power that we're discussing here today, which is the power to stop and detain someone on public rights-of-way that run through a reservation, that the --"},{"src":"argument","who":"Mr. Feigin","text":"I think it's pretty clear from Strate and I -- I believe Your Honor's opinion in Atkinson that the authority we're talking about today is meaningfully different."},{"src":"argument","who":"Mr. Feigin","text":"Well, I do think it has broader implications for Indian sovereignty, and I -- I would urge the Court to keep Montana where -- where I think it has always been. And I do think Strate and Atkinson reflect an understanding by the Court that this isn't a Montana situation, but --"}]},{"t":"case","label":"Terry v. Ohio","cite":"392 U.S. 1","y":1968,"id":"1967/67","sc":1,"by":{"0":"11, 34, 42"}},{"t":"case","label":"United States v. Brisk","cite":"171 F.3d 514","y":1999,"url":"https://www.courtlistener.com/c/F.3d/171/514/","by":{"0":"4"}},{"t":"case","label":"United States v. Bryant","cite":"136 S. Ct. 1954","y":2016,"id":"2015/15-420","sc":1,"by":{"0":"3, 17, 45"}},{"t":"case","label":"United States v. Di Re","cite":"332 U.S. 581","y":1948,"id":"scdb/1947-021","sc":1,"by":{"0":"18","1":"17, 18","2":"3"}},{"t":"case","label":"United States v. Hensley","cite":"469 U.S. 221","y":1985,"id":"1984/83-1330","sc":1,"by":{"0":"42"}},{"t":"case","label":"United States v. John","cite":"437 U.S. 634","y":1978,"id":"1977/77-836","sc":1,"by":{"0":"3"}},{"t":"case","label":"United States v. Jorn","cite":"400 U.S. 470","y":1971,"id":"1970/19","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"very vital interest in enforcement of criminal laws,","cite":"400 U.S. 470, 479"}]},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"by":{"0":"3, 20","1":"21"},"q":[{"src":"argument","who":"Justice Thomas","text":"Do you, in your discussion with the Chief Justice with respect to Montana, do you think that -- you know, Lara was decided after that and it seemed to undercut Montana."},{"src":"argument","who":"Mr. Feigin","text":"After Lara, you have Plains Commerce Bank, which very clearly applies Montana in the contexts to which I -- I think it's clearly applicable, namely, civil, regulatory, and adjudicatory legislation."}]},{"t":"case","label":"United States v. Lester","cite":"647 F.2d 869","y":1981,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/647/869/","by":{"0":"34"}},{"t":"case","label":"United States v. Mazurie","cite":"419 U.S. 544","y":1975,"id":"1974/73-1018","sc":1,"by":{"0":"18, 32","1":"15"},"q":[{"src":"brief","b":0,"text":"attributes of sovereignty over both their members and their territory.","cite":"419 U.S. 544, 557"},{"src":"brief","b":1,"text":"unique aggregations possessing attributes of sovereignty over both their members and their territory.","cite":"419 U.S. 544, 557"}]},{"t":"case","label":"United States v. Smith","cite":"899 F.2d 116","y":1990,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/899/116/","by":{"0":"18","1":"17, 18","2":"4"}},{"t":"case","label":"United States v. Terry","cite":"400 F.3d 575","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/400/575/","by":{"0":"46"}},{"t":"case","label":"United States v. Wheeler","cite":"435 U.S. 313","y":1978,"id":"1977/76-1629","sc":1,"by":{"0":"passim","1":"16, 21","2":"4, 5, 10, 11, 16"},"q":[{"src":"brief","b":0,"text":"withdrawn by treaty or statute, or by implication as a result of their dependent status.","cite":"435 U.S. 313, 323"},{"src":"brief","b":0,"text":"incorporation within the territory of the United States,","cite":"435 U.S. 313, 323"},{"src":"brief","b":1,"text":"sovereignty that the Indian tribes retain is of a unique and limited character.","cite":"435 U.S. 313, 323"},{"src":"brief","b":2,"text":"Indian tribes * * * are a good deal more than ‘private, voluntary organizations.’","cite":"435 U.S. at 323"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"sovereignty that the Indian tribes retain is of a unique and limited character.","cite":"435 U. S. 313, 323"},{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"enter into direct commercial or governmental relations with foreign nations.","cite":"435 U. S., at 326"}]},{"t":"case","label":"United States v. Winans","cite":"198 U.S. 371","y":1905,"id":"scdb/1904-073","sc":1,"by":{"0":"27"}},{"t":"case","label":"Washington v. Confederated Tribes of Colville Indian Reservation","cite":"447 U.S. 134","y":1980,"id":"1979/78-630","sc":1,"by":{"0":"19","1":"11, 18, 19","2":"5, 10"},"q":[{"src":"brief","b":0,"text":"Tribal powers are not implicitly divested by virtue of the tribes’ dependent status.","cite":"447 U.S. 134, 153"}]},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"passim"}},{"t":"usc","label":"26 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/26/1301","by":{"0":"3, 21"}},{"t":"usc","label":"25 U.S.C. § 1301","url":"https://www.law.cornell.edu/uscode/text/25/1301","subs":["(2)"],"stext":{"head":"§1301. Definitions","paras":[[0,"For purposes of this subchapter, the term—"],[0,"(1) \"Indian tribe\" means any tribe, band, or other group of Indians subject to the jurisdiction of the United States and recognized as possessing powers of self-government;"],[0,"(2) \"powers of self-government\" means and includes all governmental powers possessed by an Indian tribe, executive, legislative, and judicial, and all offices, bodies, and tribunals by and through which they are executed, including courts of Indian offenses; and means the inherent power of Indian tribes, hereby recognized and affirmed, to exercise criminal jurisdiction over all Indians;"],[0,"(3) \"Indian court\" means any Indian tribal court or court of Indian offense; and"],[0,"(4) \"Indian\" means any person who would be subject to the jurisdiction of the United States as an Indian under section 1153, title 18, if that person were to commit an offense listed in that section in Indian country to which that section applies."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1301?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3, 21","1":"8, 37","2":"9"},"q":[{"src":"brief","b":1,"text":"all governmental powers possessed by an Indian tribe, executive, legislative, and judicial, and all offices, bodies, and tribunals by and through which they are executed, including courts of Indian offenses; and . . . the inherent power of Indian tribes, hereby recognized and affirmed, to exercise criminal jurisdiction over all Indians.","cite":"25 U.S.C. §§ 1301(2), 1302"}]},{"t":"usc","label":"25 U.S.C. § 1302","url":"https://www.law.cornell.edu/uscode/text/25/1302","subs":["(a)(2)"],"stext":{"head":"§1302. Constitutional rights","paras":[[0,"(a) In general"],[0,"No Indian tribe in exercising powers of self-government shall—"],[1,"(1) make or enforce any law prohibiting the free exercise of religion, or abridging the freedom of speech, or of the press, or the right of the people peaceably to assemble and to petition for a redress of grievances;"],[1,"(2) violate the right of the people to be secure in their persons, houses, papers, and effects against unreasonable search and seizures, nor issue warrants, but upon probable cause, supported by oath or affirmation, and particularly describing the place to be searched and the person or thing to be seized;"],[1,"(3) subject any person for the same offense to be twice put in jeopardy;"],[1,"(4) compel any person in any criminal case to be a witness against himself;"],[1,"(5) take any private property for a public use without just compensation;"],[1,"(6) deny to any person in a criminal proceeding the right to a speedy and public trial, to be informed of the nature and cause of the accusation, to be confronted with the witnesses against him, to have compulsory process for obtaining witnesses in his favor, and at his own expense to have the assistance of counsel for his defense (except as provided in subsection (b));"],[1,"(7)(A) require excessive bail, impose excessive fines, or inflict cruel and unusual punishments;"],[1,"(B) except as provided in subparagraph (C), impose for conviction of any 1 offense any penalty or punishment greater than imprisonment for a term of 1 year or a fine of $5,000, or both;"],[1,"(C) subject to subsection (b), impose for conviction of any 1 offense any penalty or punishment greater than imprisonment for a term of 3 years or a fine of $15,000, or both; or"],[1,"(D) impose on a person in a criminal proceeding a total penalty or punishment greater than imprisonment for a term of 9 years;"],[1,"(8) deny to any person within its jurisdiction the equal protection of its laws or deprive any person of liberty or property without due process of law;"],[1,"(9) pass any bill of attainder or ex post facto law; or"],[1,"(10) deny to any person accused of an offense punishable by imprisonment the right, upon request, to a trial by jury of not less than six persons."],[0,"(b) Offenses subject to greater than 1-year imprisonment or a fine greater than $5,000"],[0,"A tribal court may subject a defendant to a term of imprisonment greater than 1 year but not to exceed 3 years for any 1 offense, or a fine greater than $5,000 but not to exceed $15,000, or both, if the defendant is a person accused of a criminal offense who—"],[1,"(1) has been previously convicted of the same or a comparable offense by any jurisdiction in the United States; or"],[1,"(2) is being prosecuted for an offense comparable to an offense that would be punishable by more than 1 year of imprisonment if prosecuted by the United States or any of the States."],[0,"(c) Rights of defendants"],[0,"In a criminal proceeding in which an Indian tribe, in exercising powers of self-government, imposes a total term of imprisonment of more than 1 year on a defendant, the Indian tribe shall—"],[1,"(1) provide to the defendant the right to effective assistance of counsel at least equal to that guaranteed by the United States Constitution; and"],[1,"(2) at the expense of the tribal government, provide an indigent defendant the assistance of a defense attorney licensed to practice law by any jurisdiction in the United States that applies appropriate professional licensing standards and effectively ensures the competence and professional responsibility of its licensed attorneys;"],[1,"(3) require that the judge presiding over the criminal proceeding—"],[2,"(A) has sufficient legal training to preside over criminal proceedings; and"],[2,"(B) is licensed to practice law by any jurisdiction in the United States;"],[1,"(4) prior to charging the defendant, make publicly available the criminal laws (including regulations and interpretative documents), rules of evidence, and rules of criminal procedure (including rules governing the recusal of judges in appropriate circumstances) of the tribal government; and"],[1,"(5) maintain a record of the criminal proceeding, including an audio or other recording of the trial proceeding."],[0,"(d) Sentences"],[0,"In the case of a defendant sentenced in accordance with subsections (b) and (c), a tribal court may require the defendant—"],[1,"(1) to serve the sentence—"],[2,"(A) in a tribal correctional center that has been approved by the Bureau of Indian Affairs for long-term incarceration, in accordance with guidelines to be developed by the Bureau of Indian Affairs (in consultation with Indian tribes) not later than 180 days after July 29, 2010;"],[2,"(B) in the nearest appropriate Federal facility, at the expense of the United States pursuant to the Bureau of Prisons tribal prisoner pilot program described in section 304(c) 1 of the Tribal Law and Order Act of 2010;"],[2,"(C) in a State or local government-approved detention or correctional center pursuant to an agreement between the Indian tribe and the State or local government; or"],[2,"(D) in an alternative rehabilitation center of an Indian tribe; or"],[1,"(2) to serve another alternative form of punishment, as determined by the tribal court judge pursuant to tribal law."],[0,"(e) Definition of offense"],[0,"In this section, the term \"offense\" means a violation of a criminal law."],[0,"(f) Effect of section"],[0,"Nothing in this section affects the obligation of the United States, or any State government that has been delegated authority by the United States, to investigate and prosecute any criminal violation in Indian country."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/1302?type=usc&year=mostrecent&link-type=html"},"by":{"0":"8, 21, 34","1":"37, 38","2":"9"}},{"t":"usc","label":"18 U.S.C. § 13","url":"https://www.law.cornell.edu/uscode/text/18/13","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(c)(1)(A)"],"by":{"0":"2, 8"}},{"t":"usc","label":"18 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/18/1151","subs":["(a)"],"stext":{"head":"§1151. Indian country defined","paras":[[0,"Except as otherwise provided in sections 1154 and 1156 of this title, the term \"Indian country\", as used in this chapter, means (a) all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and, including rights-of-way running through the reservation, (b) all dependent Indian communities within the borders of the United States whether within the original or subsequently acquired territory thereof, and whether within or without the limits of a state, and (c) all Indian allotments, the Indian titles to which have not been extinguished, including rights-of-way running through the same."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1151?type=usc&year=mostrecent&link-type=html"},"by":{"0":"39, 2, 21, 28, 20","1":"23","2":"9, 10"},"q":[{"src":"brief","b":0,"text":"all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and, including rights-of-way running through the reservation.","cite":"18 U.S.C. 1151(a)"},{"src":"brief","b":2,"text":"all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and including rights-of-way running through the reservation.","cite":"18 U.S.C. 1151(a)"}]},{"t":"usc","label":"18 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/18/1152","stext":{"head":"§1152. Laws governing","paras":[[0,"Except as otherwise expressly provided by law, the general laws of the United States as to the punishment of offenses committed in any place within the sole and exclusive jurisdiction of the United States, except the District of Columbia, shall extend to the Indian country."],[0,"This section shall not extend to offenses committed by one Indian against the person or property of another Indian, nor to any Indian committing any offense in the Indian country who has been punished by the local law of the tribe, or to any case where, by treaty stipulations, the exclusive jurisdiction over such offenses is or may be secured to the Indian tribes respectively."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1152?type=usc&year=mostrecent&link-type=html"},"by":{"0":"3","1":"23","2":"9, 10"}},{"t":"usc","label":"18 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/18/1153","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 1162","url":"https://www.law.cornell.edu/uscode/text/18/1162","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","by":{"0":"20"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)"],"by":{"0":"20, 2, 8"}},{"t":"case","label":"Begay v. United States","cite":"219 Ct. Cl. 599","y":1979,"url":"https://www.courtlistener.com/c/Ct.%20Cl./219/599/","by":{"1":"35"}},{"t":"case","label":"Begay v. United States","cite":"224 Ct. Cl. 712","y":1980,"url":"https://www.courtlistener.com/c/Ct.%20Cl./224/712/","by":{"1":"35"}},{"t":"case","label":"Cheyenne & Arapaho Tribes v. United States","cite":"2020 WL 7251080","y":2020,"court":"Fed. Cl. Dec. 9","by":{"1":"34"}},{"t":"case","label":"Elk v. United States","cite":"87 Fed. Cl. 70","y":2009,"url":"https://www.courtlistener.com/c/Fed.%20Cl./87/70/","by":{"1":"35"}},{"t":"case","label":"Hebah v. United States","cite":"428 F.2d 1334","y":1970,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/428/1334/","by":{"1":"34"}},{"t":"case","label":"Jones v. United States","cite":"846 F.3d 1343","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/846/1343/","by":{"1":"35"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co. of America","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"by":{"1":"23"},"q":[{"src":"brief","b":1,"text":"It is to the holdings of our cases, rather than their dicta, that [the Court] must attend[.]","cite":"511 U.S. 375, 379"}]},{"t":"case","label":"McGirt v. Oklahoma","cite":"140 S. Ct. 2452","y":2020,"id":"2019/18-9526","sc":1,"by":{"1":"12, 25, 26"},"q":[{"src":"brief","b":1,"text":"Jurisdictional gaps are hardly foreign to this area of law.","cite":"140 S. Ct. at 2478"}]},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"by":{"1":"27"},"q":[{"src":"brief","b":1,"text":"fundamental commitment of Indian law [which] is judicial respect for Congress’s primary role in defining the contours of tribal sovereignty.","cite":"572 U.S. 782, 803"}]},{"t":"case","label":"Nevada v. Hicks","cite":"533 U.S. 353","y":2001,"id":"2000/99-1994","sc":1,"by":{"1":"13, 16, 37"},"q":[{"src":"brief","b":1,"text":"Where nonmembers are concerned, the ‘exercise of tribal power beyond what is necessary to protect tribal selfgovernment or to control internal relations is inconsistent with the dependent status of the tribes, and so cannot survive without express congressional delegation.’","cite":"533 U.S. 353, 359"},{"src":"brief","b":1,"text":"exercise of tribal power [went] beyond what is necessary to protect tribal self-government or to control internal relations,","cite":"533 U.S. at 359"}]},{"t":"case","label":"Richard v. United States","cite":"677 F.3d 1141","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/677/1141/","by":{"1":"35"}},{"t":"case","label":"Singelton v. Wulff","cite":"428 U.S. 106","y":1976,"id":"1975/74-1393","sc":1,"by":{"1":"30"}},{"t":"case","label":"South Dakota v. Bourland","cite":"508 U.S. 679","y":1993,"id":"1992/91-2051","sc":1,"by":{"1":"20"},"q":[{"src":"argument","who":"Chief Justice Roberts","text":"But, as we said in South Dakota versus Bourland, describing Montana, and this is a quote, it said, \"After Montana, tribal sovereignty over non-members cannot survive without express congressional delegation and is, therefore, not inherent.\" So I would have described that as at least one source that says the opposite of what you said."}]},{"t":"case","label":"Tsosie v. United States","cite":"825 F.2d 393","y":1987,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.2d/825/393/","by":{"1":"35"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"by":{"1":"19"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"by":{"1":"19"}},{"t":"usc","label":"21 U.S.C. § 878","url":"https://www.law.cornell.edu/uscode/text/21/878","subs":["(a)(3)"],"stext":{"head":"§878. Powers of enforcement personnel","paras":[[0,"(a) Any officer or employee of the Drug Enforcement Administration or any State, tribal, or local law enforcement officer designated by the Attorney General may—"],[1,"(1) carry firearms;"],[1,"(2) execute and serve search warrants, arrest warrants, administrative inspection warrants, subpenas, and summonses issued under the authority of the United States;"],[1,"(3) make arrests without warrant (A) for any offense against the United States committed in his presence, or (B) for any felony, cognizable under the laws of the United States, if he has probable cause to believe that the person to be arrested has committed or is committing a felony;"],[1,"(4) make seizures of property pursuant to the provisions of this subchapter; and"],[1,"(5) perform such other law enforcement duties as the Attorney General may designate."],[0,"(b) State and local law enforcement officers performing functions under this section shall not be deemed Federal employees and shall not be subject to provisions of law relating to Federal employees, except that such officers shall be subject to section 3374(c) of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/878?type=usc&year=mostrecent&link-type=html"},"by":{"1":"29, 30","2":"18"},"q":[{"src":"brief","b":1,"text":"any State, tribal, or local law enforcement officer designated by the Attorney General may . . . make [warrantless arrests] (A) for any offense against the United States committed in his presence, or (B) for any felony, cognizable under the laws of the United States, if he has probable cause[.]","cite":"21 U.S.C. § 878(a)(3)"}]},{"t":"usc","label":"25 U.S.C. § 2801","url":"https://www.law.cornell.edu/uscode/text/25/2801","subs":["(7)"],"by":{"1":"28"},"q":[{"src":"brief","b":1,"text":"an offense against the United States and includes a violation of a Federal regulation relating to part or all of Ind ian co untry.","cite":"25 U.S.C. § 2801(7)"}]},{"t":"usc","label":"25 U.S.C. § 2803","url":"https://www.law.cornell.edu/uscode/text/25/2803","subs":["(3)","(5)"],"by":{"1":"28, 29","2":"18, 18, 18"}},{"t":"usc","label":"25 U.S.C. § 2804","url":"https://www.law.cornell.edu/uscode/text/25/2804","subs":["(a)(2)","(a)(3)(A)","(a)(3)(B)(ii)"],"stext":{"head":"§2804. Assistance by other agencies","paras":[[0,"(a) Agreements"],[0,"(1) In general"],[1,"Not later than 180 days after July 29, 2010, the Secretary shall establish procedures to enter into memoranda of agreement for the use (with or without reimbursement) of the personnel or facilities of a Federal, tribal, State, or other government agency to aid in the enforcement or carrying out in Indian country of a law of either the United States or an Indian tribe that has authorized the Secretary to enforce tribal laws."],[0,"(2) Certain activities"],[1,"The Secretary may authorize a law enforcement officer of such an agency to perform any activity the Secretary may authorize under section 2803 of this title."],[0,"(3) Program enhancement"],[0,"(A) Training sessions in Indian country"],[0,"(i) In general"],[3,"The procedures described in paragraph (1) shall include the development of a plan to enhance the certification and provision of special law enforcement commissions to tribal law enforcement officials, and, subject to subsection (d), State and local law enforcement officials, pursuant to this section."],[0,"(ii) Inclusions"],[3,"The plan under clause (i) shall include the hosting of regional training sessions in Indian country, not less frequently than biannually, to educate and certify candidates for the special law enforcement commissions."],[0,"(B) Memoranda of agreement"],[0,"(i) In general"],[3,"Not later than 180 days after July 29, 2010, the Secretary, in consultation with Indian tribes and tribal law enforcement agencies, shall develop minimum requirements to be included in special law enforcement commission agreements pursuant to this section."],[0,"(ii) Substance of agreements"],[3,"Each agreement entered into pursuant to this section shall reflect the status of the applicable certified individual as a Federal law enforcement officer under subsection (f), acting within the scope of the duties described in section 2802(c) of this title."],[0,"(iii) Agreement"],[3,"Not later than 60 days after the date on which the Secretary determines that all applicable requirements under clause (i) are met, the Secretary shall offer to enter into a special law enforcement commission agreement with the Indian tribe."],[0,"(b) Agreement to be in accord with agreements between Secretary and Attorney General"],[0,"Any agreement entered into under this section relating to the enforcement of the criminal laws of the United States shall be in accord with any agreement between the Secretary and the Attorney General of the United States."],[0,"(c) Limitations on use of personnel of non-Federal agency"],[0,"The Secretary may not use the personnel of a non-Federal agency under this section in an area of Indian country if the Indian tribe having jurisdiction over such area of Indian country has adopted a resolution objecting to the use of the personnel of such agency. The Secretary shall consult with Indian tribes before entering into any agreement under subsection (a) with a non-Federal agency that will provide personnel for use in any area under the jurisdiction of such Indian tribes."],[0,"(d) Authority of Federal agency head to enter into agreement with Secretary"],[0,"Notwithstanding the provisions of section 1535 of title 31, the head of a Federal agency with law enforcement personnel or facilities may enter into an agreement (with or without reimbursement) with the Secretary under subsection (a)."],[0,"(e) Authority of Federal agency head to enter into agreement with Indian tribe"],[0,"The head of a Federal agency with law enforcement personnel or facilities may enter into an agreement (with or without reimbursement) with an Indian tribe relating to—"],[1,"(1) the law enforcement authority of the Indian tribe, or"],[1,"(2) the carrying out of a law of either the United States or the Indian tribe."],[0,"(f) Status of person as Federal employee"],[0,"While acting under authority granted by the Secretary under subsection (a), a person who is not otherwise a Federal employee shall be considered to be—"],[1,"(1) an employee of the Department of the Interior only for purposes of—"],[2,"(A) the provisions of law described in section 3374(c)(2) of title 5, and"],[2,"(B) sections 111 and 1114 of title 18, and"],[1,"(2) an eligible officer under subchapter III of chapter 81 of title 5."],[0,"(g) Acceptance of assistance"],[0,"The Bureau may accept reimbursement, resources, assistance, or funding from—"],[1,"(1) a Federal, tribal, State, or other government agency; or"],[1,"(2) the Indian Law Enforcement Foundation established under section 5412(a) 1 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2804?type=usc&year=mostrecent&link-type=html"},"by":{"1":"28, 29","2":"18, 19, 19, 18, 18"},"q":[{"src":"brief","b":1,"text":"authorize a law enforcement officer of [any Federal, tribal, State, or other government agency] to perform any activity the Secretary may authorize under section 2803 of this title.","cite":"25 U.S.C. § 2804(a)(1)"},{"src":"brief","b":1,"text":"relating to (1) the law enforcement authority of the Indian tribe, or (2) the carrying out of a law of . . . the United States[.]","cite":"25 U.S.C. § 2804(e)"}]},{"t":"usc","label":"25 U.S.C. § 2805","url":"https://www.law.cornell.edu/uscode/text/25/2805","by":{"1":"29"}},{"t":"reg","label":"25 C.F.R. § 12.21","url":"https://www.ecfr.gov/current/title-25/section-12.21","by":{"1":"29"},"q":[{"src":"brief","b":1,"text":"issue law enforcement commissions to . . . tribal full-time certified law enforcement officers to obtain active assistance in e nforcing applicable Federal criminal statutes[.]","cite":"25 C.F.R. § 12.21"}]},{"t":"case","label":"Arizona v. San Carlos Apache Tribe","cite":"463 U.S. 545","y":1983,"id":"1982/81-2147","sc":1,"by":{"2":"5"},"q":[{"src":"brief","b":2,"text":"tribes retain any aspect of their historical sovereignty not ‘inconsistent with the overriding interests of the National Government.’","cite":"463 U.S. 545, 571"}]},{"t":"case","label":"Brendale v. Confederated Tribes & Bands of the Yakima Indian Nation","cite":"492 U.S. 406","y":1989,"id":"1988/88-309","sc":1,"by":{"2":"6"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Breyer)","text":"have inherent sovereignty independent of th[e] authority arising from their power to exclude,","cite":"492 U. S., at 425"}]},{"t":"case","label":"Commonwealth v. Craan","cite":"13 N.E.3d 569","y":2014,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.3d/13/569/","by":{"2":"4"}},{"t":"case","label":"Gonzales v. City of Peoria","cite":"722 F.2d 468","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/722/468/","by":{"2":"4"}},{"t":"case","label":"Johnson v. United States","cite":"333 U.S. 10","y":1948,"id":"scdb/1947-031","sc":1,"by":{"2":"3"}},{"t":"case","label":"Ker v. California","cite":"374 U.S. 23","y":1963,"id":"1962/53","sc":1,"by":{"2":"3"}},{"t":"case","label":"(I) Cases—Continued: New Mexico v. Mescalero Apache Tribe","cite":"462 U.S. 324","y":1983,"id":"1982/82-331","sc":1,"by":{"2":"5"}},{"t":"case","label":"People v. LaFontaine","cite":"705 N.E.2d 663","y":1998,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E.2d/705/663/","by":{"2":"4"}},{"t":"case","label":"United States v. Bowdach","cite":"561 F.2d 1160","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/561/1160/","by":{"2":"4"}},{"t":"case","label":"United States v. Janik","cite":"723 F.2d 537","y":1983,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/723/537/","by":{"2":"4"}},{"t":"case","label":"United States v. Turner","cite":"553 F.3d 1337","y":2009,"url":"https://www.courtlistener.com/c/F.3d/553/1337/","by":{"2":"4"}},{"t":"case","label":"Virginia v. Moore","cite":"553 U.S. 164","y":2008,"id":"2007/06-1082","sc":1,"by":{"2":"3"}},{"t":"const","label":"Article IV, Section 2, Clause 2","text":"A Person charged in any State with Treason, Felony, or other Crime, who shall flee from Justice, and be found in another State, shall on Demand of the executive Authority of the State from which he fled, be delivered up, to be removed to the State having Jurisdiction of the Crime.","by":{"2":"2, 6"}},{"t":"const","label":"Article V","clauses":[["article-v","Article V: Amending the Constitution"]],"text":"The Congress, whenever two thirds of both Houses shall deem it necessary, shall propose Amendments to this Constitution, or, on the Application of the Legislatures of two thirds of the several States, shall call a Convention for proposing Amendments, which, in either Case, shall be valid to all Intents and Purposes, as Part of this Constitution, when ratified by the Legislatures of three fourths of the several States, or by Conventions in three fourths thereof, as the one or the other Mode of Ratification may be proposed by the Congress; Provided that no Amendment which may be made prior to the Year One thousand eight hundred and eight shall in any Manner affect the first and fourth Clauses in the Ninth Section of the first Article; and that no State, without its Consent, shall be deprived of its equal Suffrage in the Senate.","by":{"2":"7, 8"}},{"t":"const","label":"Article VI","clauses":[["supremacy","Supremacy Clause"],["religious-test","No Religious Test Clause"]],"text":"All Debts contracted and Engagements entered into, before the Adoption of this Constitution, shall be as valid against the United States under this Constitution, as under the Confederation. This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding. The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"2":"7"}},{"t":"usc","label":"5 U.S.C. § 3374","url":"https://www.law.cornell.edu/uscode/text/5/3374","subs":["(c)(2)"],"by":{"2":"18"}},{"t":"usc","label":"5 U.S.C. § 8191","url":"https://www.law.cornell.edu/uscode/text/5/8191","by":{"2":"18"}}]};